try {
  // --- UNIVERSAL ADAPTER (Supports HTTP Node & LangChain Agent) ---
  const json = $input.item.json;
  const response = json.output || json.text || (json.choices && json.choices[0]?.message?.content) || json.message?.content;
  if (!response) {
    throw new Error('STRUCTURAL_ERROR: Không tìm thấy nội dung phản hồi từ AI. Output Node không đúng chuẩn.');
  }
  // ------------------------------------------------------------------

  let parsed;
  try {
    parsed = JSON.parse(response);
  } catch (e) {
    throw new Error('STRUCTURAL_ERROR: Agent 1 did not return valid JSON.');
  }

  const requiredSections = [
    "executive_decision", "icp_and_pain_wedge", "offer", "funnel_architecture",
    "crm_role", "chatbot_role", "creative_architecture", "media_buying_structure",
    "10_day_operating_plan", "lead_qualification", "sales_handoff", "organic_trust_layer",
    "measurement_framework", "budget_allocation", "risks_policy", "day_3_gate", "day_6_gate",
    "end_of_pilot_decision_framework", "assets_required_before_launch", "do_not_do",
    "daily_timeline", "uses_ads", "needs_clarification", "clarification_questions", "assumptions_to_confirm"
  ];

  const missingSections = requiredSections.filter((key) => !(key in parsed));
  if (missingSections.length > 0) {
    throw new Error('STRUCTURAL_ERROR: Agent 1 output is missing required sections: ' + missingSections.join(', '));
  }

  if (!Array.isArray(parsed.daily_timeline)) {
    throw new Error('STRUCTURAL_ERROR: `daily_timeline` must be an array.');
  }

  parsed.daily_timeline.forEach((dayPlan, index) => {
    if (Array.isArray(dayPlan) || !dayPlan || typeof dayPlan !== 'object') {
      throw new Error(`STRUCTURAL_ERROR: daily_timeline[${index}] must be an object.`);
    }
    const requiredDayKeys = ['day', 'objective', 'channel', 'creative', 'budget_vnd', 'metric', 'gate'];
    const missingKeys = requiredDayKeys.filter((key) => !(key in dayPlan));
    if (missingKeys.length > 0) {
      throw new Error(`STRUCTURAL_ERROR: daily_timeline[${index}] is missing keys: ${missingKeys.join(', ')}`);
    }
    for (const key of requiredDayKeys) {
      const value = dayPlan[key];
      if (value == null) {
        throw new Error(`STRUCTURAL_ERROR: daily_timeline[${index}].${key} is empty.`);
      }
      if (typeof value === 'string' && !value.trim()) {
        throw new Error(`STRUCTURAL_ERROR: daily_timeline[${index}].${key} is empty.`);
      }
    }
    if (!Number.isInteger(dayPlan.day) || dayPlan.day < 1) {
      throw new Error(`STRUCTURAL_ERROR: daily_timeline[${index}].day must be a positive integer.`);
    }

    if (typeof dayPlan.budget_vnd !== 'number' || !Number.isFinite(dayPlan.budget_vnd) || dayPlan.budget_vnd < 0) {
      throw new Error(`STRUCTURAL_ERROR: daily_timeline[${index}].budget_vnd must be a zero or positive number.`);
    }
  });

  if (typeof parsed.uses_ads !== 'boolean') {
    throw new Error('STRUCTURAL_ERROR: `uses_ads` must be a boolean.');
  }
  if (typeof parsed.needs_clarification !== 'boolean') {
    throw new Error('STRUCTURAL_ERROR: `needs_clarification` must be a boolean.');
  }

  if (!Array.isArray(parsed.clarification_questions)) {
    throw new Error('STRUCTURAL_ERROR: `clarification_questions` must be an array.');
  }
  if (!parsed.clarification_questions.every(q => typeof q === 'string')) {
    throw new Error('STRUCTURAL_ERROR: `clarification_questions` must be an array of strings.');
  }

  if (!Array.isArray(parsed.assumptions_to_confirm)) {
    throw new Error('STRUCTURAL_ERROR: `assumptions_to_confirm` must be an array.');
  }
  if (!parsed.assumptions_to_confirm.every(a => typeof a === 'string')) {
    throw new Error('STRUCTURAL_ERROR: `assumptions_to_confirm` must be an array of strings.');
  }

  const needsClarification = parsed.needs_clarification === true;
  const clarificationQuestions = parsed.clarification_questions.filter((question) => question.trim());

  if (needsClarification) {
    return {
      json: {
        ...$input.item.json,
        needs_clarification: true,
        clarification_questions: clarificationQuestions,
        reason: typeof parsed.reason === 'string' && parsed.reason.trim() ? parsed.reason : 'NEEDS_CLARIFICATION'
      }
    };
  }

  const scope = $node['Scope Resolve'].json;
  const contract = scope.campaign_contract || {};
  const paidMediaAllowed = contract.paid_media_allowed;

  if (Number.isInteger(contract.campaign_duration_days)) {
    const expectedDays = contract.campaign_duration_days;
    const timelineLength = parsed.daily_timeline.length;
    if (timelineLength !== expectedDays) {
      throw new Error('VALIDATION_ERROR: Expected exactly ' + expectedDays + ' days, got ' + timelineLength);
    }
  }

  if (paidMediaAllowed === false && parsed.uses_ads !== false) {
    throw new Error('VALIDATION_ERROR: Strategy uses ads despite paid_media_allowed=false.');
  }

  return {
    json: {
      ...$input.item.json,
      needs_clarification: false,
      clarification_questions: []
    }
  };

} catch (error) {
  // ĐÂY LÀ ĐOẠN CATCH LỖI ĐỂ TRÁNH CRASH N8N
  return {
    json: {
      ...$input.item.json,
      needs_clarification: true,
      clarification_questions: ["LỖI HỆ THỐNG NỘI BỘ (AI sinh JSON lỗi cấu trúc): " + error.message + " --- Sếp vui lòng ra lệnh lại và NHẮC AI làm ĐÚNG CẤU TRÚC nhé!"],
      reason: "SYSTEM_VALIDATION_ERROR"
    }
  };
}

